UPDATE {{ ref('q_code__reject') }} SET resolved_at = CURRENT_TIMESTAMP, last_evaluated_at = CURRENT_TIMESTAMP
WHERE
  resolved_at IS NULL
  AND _source_row_id IN (
    SELECT
      _target._source_row_id
    FROM {{ ref('q_code') }} AS _target
  )
  {% endset %}
  {% do run_query(statement_1) %}
  {% set statement_2 %}
MERGE INTO {{ ref('q_code__reject') }} AS _target
USING (
  SELECT
    _extract._source_row_id,
    ARRAY_CAT(
      ARRAY_CAT(
        ARRAY_CAT(
          ARRAY_CAT(
            ARRAY_CAT(
              ARRAY_CAT(
                ARRAY_CAT(
                  CASE
                    WHEN NOT COALESCE(
                      (
                        _extract._branch_code_fail_coercible
                        OR _extract._branch_code_flag_coercible
                        OR _extract._branch_code_id_coercible
                        OR _extract._branch_code_quar_coercible
                        OR _extract._win_code_quar_unique
                      ),
                      FALSE
                    )
                    THEN ARRAY['(superseded)']
                    ELSE CAST(ARRAY[] AS TEXT[])
                  END,
                  CASE
                    WHEN _extract._branch_code_fail_coercible
                    THEN ARRAY['code_fail_coercible']
                    ELSE CAST(ARRAY[] AS TEXT[])
                  END
                ),
                CASE
                  WHEN _extract._win_code_fail_unique
                  THEN ARRAY['code_fail_unique']
                  ELSE CAST(ARRAY[] AS TEXT[])
                END
              ),
              CASE
                WHEN _extract._branch_code_flag_coercible
                THEN ARRAY['code_flag_coercible']
                ELSE CAST(ARRAY[] AS TEXT[])
              END
            ),
            CASE
              WHEN _extract._win_code_flag_unique
              THEN ARRAY['code_flag_unique']
              ELSE CAST(ARRAY[] AS TEXT[])
            END
          ),
          CASE
            WHEN _extract._branch_code_id_coercible
            THEN ARRAY['code_id_coercible']
            ELSE CAST(ARRAY[] AS TEXT[])
          END
        ),
        CASE
          WHEN _extract._branch_code_quar_coercible
          THEN ARRAY['code_quar_coercible']
          ELSE CAST(ARRAY[] AS TEXT[])
        END
      ),
      CASE
        WHEN _extract._win_code_quar_unique
        THEN ARRAY['code_quar_unique']
        ELSE CAST(ARRAY[] AS TEXT[])
      END
    ) AS failed_rules
  FROM (
    SELECT
      *,
      (
        COUNT(*) OVER (PARTITION BY code_fail) > 1 AND (
          NOT code_fail IS NULL
        )
      ) AS _win_code_fail_unique,
      (
        COUNT(*) OVER (PARTITION BY code_flag) > 1 AND (
          NOT code_flag IS NULL
        )
      ) AS _win_code_flag_unique,
      (
        COUNT(*) OVER (PARTITION BY code_quar) > 1 AND (
          NOT code_quar IS NULL
        )
      ) AS _win_code_quar_unique
    FROM (
      SELECT
        CASE
          WHEN PG_INPUT_IS_VALID(JSON_EXTRACT_PATH_TEXT(raw, '$.code_fail'), 'TEXT')
          THEN CAST(JSON_EXTRACT_PATH_TEXT(raw, '$.code_fail') AS TEXT)
        END AS code_fail,
        CASE
          WHEN PG_INPUT_IS_VALID(JSON_EXTRACT_PATH_TEXT(raw, '$.code_flag'), 'TEXT')
          THEN CAST(JSON_EXTRACT_PATH_TEXT(raw, '$.code_flag') AS TEXT)
        END AS code_flag,
        CASE
          WHEN PG_INPUT_IS_VALID(JSON_EXTRACT_PATH_TEXT(raw, '$.code_id'), 'TEXT')
          THEN CAST(JSON_EXTRACT_PATH_TEXT(raw, '$.code_id') AS TEXT)
        END AS code_id,
        CASE
          WHEN PG_INPUT_IS_VALID(JSON_EXTRACT_PATH_TEXT(raw, '$.code_quar'), 'TEXT')
          THEN CAST(JSON_EXTRACT_PATH_TEXT(raw, '$.code_quar') AS TEXT)
        END AS code_quar,
        _ingested_at,
        _load_id,
        _source_row_id,
        CASE
          WHEN PG_INPUT_IS_VALID(JSON_EXTRACT_PATH_TEXT(raw, '$.code_fail'), 'TEXT')
          THEN CAST(JSON_EXTRACT_PATH_TEXT(raw, '$.code_fail') AS TEXT)
        END IS NULL
        AND (
          NOT JSON_EXTRACT_PATH_TEXT(raw, '$.code_fail') IS NULL
        ) AS _branch_code_fail_coercible,
        CASE
          WHEN PG_INPUT_IS_VALID(JSON_EXTRACT_PATH_TEXT(raw, '$.code_flag'), 'TEXT')
          THEN CAST(JSON_EXTRACT_PATH_TEXT(raw, '$.code_flag') AS TEXT)
        END IS NULL
        AND (
          NOT JSON_EXTRACT_PATH_TEXT(raw, '$.code_flag') IS NULL
        ) AS _branch_code_flag_coercible,
        CASE
          WHEN PG_INPUT_IS_VALID(JSON_EXTRACT_PATH_TEXT(raw, '$.code_id'), 'TEXT')
          THEN CAST(JSON_EXTRACT_PATH_TEXT(raw, '$.code_id') AS TEXT)
